import from "react" { useEffect }
import from "twilio-video" {
    LocalAudioTrack,
    LocalVideoTrack,
    RemoteAudioTrack,
    RemoteVideoTrack,
}

type TrackType = LocalAudioTrack | LocalVideoTrack | RemoteAudioTrack | RemoteVideoTrack | None;

def:pub useIsTrackEnabled(track: TrackType) -> bool {
    has is_enabled: bool = track.isEnabled if track else False;

    useEffect(lambda {
        if track {
            current = track;
            is_enabled = current.isEnabled;
            def set_enabled {
                is_enabled = True;
            }
            def set_disabled {
                is_enabled = False;

            }
            current.on("enabled", set_enabled);
            current.on("disabled", set_disabled);
            return lambda {
                current.off("enabled", set_enabled);
                current.off("disabled", set_disabled);
            };
        }
        is_enabled = False;
    }, [track]);

    return is_enabled;
}

