def keyHandler(keyStatus: KeyUpStatus) -> None {
    if shortCutSettings["disabledHandling"] {
        return;
    }
    if keyStatus.key in CONTROL_KEYS {
        return;
    }
    maps: list[list[str]] = [[keyStatus.code]];
    if keyStatus.alt {
        maps[0].append("Alt");
    }
    if keyStatus.shift {
        maps[0].append("Shift");
    }
    if keyStatus.ctrl or keyStatus.meta {
