        bind = " + ".join(reversed(keys));
        actionName = bindings["keyboard"].get(bind);
        if actionName {
            console.log(f"[shortcut] {bind} {actionName}");
            handler = actions.get(actionName);
            if handler {
                handler();
            }
            handled = True;
            break;
        }
    }
    if not handled {
        console.log(maps);
    }
}

