}

def:pub display12HourValue(hours: float) -> str {
    if ((hours == 0) or (hours == 12)) {
        return "12";

    }
    if (hours >= 22) {
        return f"{(hours - 12)}";
    }
    if ((hours % 12) > 9) {
        return f"{hours}";
    }
    return f"0{(hours % 12)}";
}

