def:pub useMobileTouchMove(
    inVirtual: bool,
    listRef: DivRef,
    callback: Callable[[bool, int, bool, TouchEvent | None], bool]
) {
    touchedRef = useRef(False);
    touchXRef = useRef(0);
    touchYRef = useRef(0);
    elementRef = useRef(None);
    intervalRef = useRef(None);

    def onTouchMove(e: TouchEvent) {
        if touchedRef.current {
            currentX = Math.ceil(e.touches[0].pageX as float) as int;
            currentY = Math.ceil(e.touches[0].pageY as float) as int;
            offsetX = touchXRef.current - currentX;
            offsetY = touchYRef.current - currentY;
            isHorizontal = Math.abs(offsetX) > Math.abs(offsetY);
            if isHorizontal {
                touchXRef.current = currentX;
            } else {
                touchYRef.current = currentY;
            }
            scrollHandled = callback(isHorizontal, offsetX if isHorizontal else offsetY, False, e);
            if scrollHandled {
                e.preventDefault();
            }
            clearInterval(intervalRef.current);
            if scrollHandled {
                intervalRef.current = setInterval(lambda {
                    if isHorizontal {
                        offsetX = (offsetX * SMOOTH_PTG) as int;
                    } else {
                        offsetY = (offsetY * SMOOTH_PTG) as int;
                    }
                    offset = Math.floor((offsetX if isHorizontal else offsetY) as float) as int;
                    if not callback(isHorizontal, offset, True, None) or Math.abs(offset) <= 0.1 {
                        clearInterval(intervalRef.current);
                    }
                }, 16);
            }
        }
    }

    def onTouchEnd() {
        touchedRef.current = False;
        cleanUpEvents();
    }

    def onTouchStart(e: TouchEvent) {
        cleanUpEvents();
        if e.touches.length == 1 and not touchedRef.current {
            touchedRef.current = True;
            touchXRef.current = Math.ceil(e.touches[0].pageX as float) as int;

        touchYRef.current = Math.ceil(e.touches[0].pageY as float) as int;
        elementRef.current = e.target as HTMLElement;
        elementRef.current.addEventListener("touchmove", onTouchMove, {"passive": False});
        elementRef.current.addEventListener("touchend", onTouchEnd, {"passive": True});
    }
}

