def get_jaccard_score(a: tuple[int, int], s: tuple[int, int]) -> float {
    a_start = a[0];
    a_end = a[0] + a[1] - 1;
    start = s[0];

    end = s[0] + s[1] - 1;
    pred_ids = set(range(start, end + 1));
