        elif ch == 'D' { digit = 13; }
        elif ch == 'E' { digit = 14; }
        elif ch == 'F' { digit = 15; }
        elif ch != int(ch) {
            print('Invalid character **', ch, '**');
            return 0;
        } else {
            digit = int(ch);
        }
