def:pub isUnplayed(windup: list[object]) -> bool {
    played = windup[0] as list[object];
    remaining = windup[1] as list[object];
    if (len(played) > 0) {
        return False;
    }
    acc = True;
    for member in remaining {
        if memberIsWindup(member) {
            if (memberIsWindup(windup) and acc) {
                acc = isUnplayed(member as list[object]);
            }
        }
    }
    return acc;
}

def:pub isFinished(windup: list[object]) -> bool {
    remaining = windup[1] as list[object];
    return (len(remaining) == 0);
}

def:pub rewind(windup: list[object]) -> list[object] {
    if isUnplayed(windup) {
        return windup;
    }
    played = windup[0] as list[object];
    remaining = windup[1] as list[object];
    metadata = windup[2];
    mapRewind = lambda (member: object) -> object {
        if memberIsWindup(member) {
            return rewind(member as list[object]);
        }
        return member;
    };
    return [[], [mapRewind(m) for m in played] + [mapRewind(m) for m in remaining], metadata];
}

def:pub windupAsString(windup: list[object]) -> str {
    played = windup[0] as list[object];
    remaining = windup[1] as list[object];
    stringify = lambda (member: object) -> str {
        if memberIsWindup(member) {

            return windupAsString(member as list[object]);
        }
        return member as str;
    };
    return "".join([stringify(m) for m in played]) + "".join([stringify(m) for m in remaining]);
}

