"""Quiz grader: typed integer reports collected across quiz nodes.

Demonstrates a walker whose `report` is strictly typed to `list[int]`,
so accidental string scores are a type error at the source. Quiz nodes
carry a student name and score, and the grader visits each one to
collect the score before exiting with the class average.
"""

node Quiz {
    has student: str = "";
    has score: int = 0;
}

walker Grader {
    has scores: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.scores.append(here.score);
        print(f"{here.student}: {here.score}");
        visit [-->];
    }

    can summarize with Root exit {
        total = 0;
        for s in self.scores {
            total = total + s;
        }
        avg = total / len(self.scores);
        print(f"Collected scores: {self.scores}");
        print(f"Class average: {avg}");
        report self.scores;
    }
}

