import from "../components/FocusContext.js" { default as FocusContext }
import from "./use-stdin.js" { default as useStdin }

obj StdinContextValue {
    has isRawModeSupported: bool;
    has setRawMode: Callable[[bool], None];
}

obj FocusRegistryValue {
    has activeId: str | None;
    has add: Callable[[str, dict[str, bool]], None];
    has remove: Callable[[str], None];
    has activate: Callable[[str], None];
    has deactivate: Callable[[str], None];
    has focus: Callable[[str], None];
}

def:pub useFocus(
    isActive: bool = True,
    autoFocus: bool = False,
    id: str | None = None
) -> dict[str, bool | Callable[[str], None]] {
    stdinCtx = useStdin() as StdinContextValue;
    isRawModeSupported = stdinCtx.isRawModeSupported;
    setRawMode = stdinCtx.setRawMode;
    focusContext = useContext(FocusContext) as FocusRegistryValue;
    activeId = focusContext.activeId;
    add = focusContext.add;
    remove = focusContext.remove;
    activate = focusContext.activate;
    deactivate = focusContext.deactivate;
    focusFn = focusContext.focus;
    componentId = useMemo(lambda { return id if id else str(Math.random())[2:7]; }, [id]);
    useEffect(lambda {
        add(componentId, {"autoFocus": autoFocus});
        return lambda { remove(componentId); };
    }, [componentId, autoFocus, add, remove]);
    useEffect(lambda {
        if isActive { activate(componentId); }
        else { deactivate(componentId); }
    }, [isActive, componentId, activate, deactivate]);
    useEffect(lambda {
        if not isRawModeSupported or not isActive { return; }
        setRawMode(True);
        return lambda { setRawMode(False); };
    }, [isActive, isRawModeSupported, setRawMode]);
    {
        "isFocused": bool(componentId) and activeId == componentId,
        "focus": focusFn
    }
}
