"""Orchard irrigation tour.

A maintenance crew walks the grove, servicing pumps and sprinklers. A
single shared routine handles both device kinds via a union trigger,
logs the device kind, resets its idle counter, and tracks totals.
"""

node Device {
    has kind: str = "";
    has idle_hours: int = 0;
}

node Pump(Device) {
    has pump_model: str = "standard";

    def service() -> int {
        logged = self.idle_hours;
        print(f"[pump] serviced after {logged} idle hours");
        self.idle_hours = 0;
        return logged;
    }
}

node Sprinkler(Device) {
    has radius_m: float = 0.0;

    def service() -> int {
        logged = self.idle_hours;
        print(f"[sprinkler] serviced after {logged} idle hours");
        self.idle_hours = 0;
        return logged;
    }
}

walker MaintenanceCrew {
    has devices_serviced: int = 0;
    has total_idle_hours: int = 0;

    can start with Root entry {
        print("Crew entering the orchard");
        visit [-->];
    }

    can tour with Pump | Sprinkler entry {
        serviced = here.service();
        self.devices_serviced += 1;
        self.total_idle_hours += serviced;
        visit [-->];
    }
}

with entry {
    root ++> Pump(kind="pump", idle_hours=12)
        ++> Sprinkler(kind="sprinkler", idle_hours=7)
        ++> Pump(kind="pump", idle_hours=3)
        ++> Sprinkler(kind="sprinkler", idle_hours=15);

    crew = MaintenanceCrew();
    root spawn crew;

    print(f"Devices serviced: {crew.devices_serviced}, "
          f"Total idle hours cleared: {crew.total_idle_hours}");
}
