        throw new ProviderError(
          ProviderErrorType.MODEL_NOT_FOUND,
          `Model "${model}" not found on Gemini.`,
          'gemini'
        );
      } else {
        throw new ProviderError(
          ProviderErrorType.UNKNOWN,
          `Gemini error: ${err?.message || 'Unknown error occurred'}`,
          'gemini'
        );
      }
    }
  }
}

