    has isIdle: bool = False;

    useEffect(lambda {
        timer_id: int | None = None;

        def reset_timer() {
            isIdle = False;
            if timer_id is not None {
                clearTimeout(timer_id);
            }
            timer_id = setTimeout(lambda { isIdle = True; }, idleDelay);
        }

        def on_activity(_e: Event) {
