def chunkMaker(array: list[str], chunkNumber: int) -> list[list[str]] {
    result: list[list[str]] = [];
    for i in range(0, len(array), chunkNumber) {
        result = result + [array[i:(i + chunkNumber)]];
    }
    return result;
}

def chunkFiller(array: list[list[str]], chunkNumber: int, padNonFullChunk: bool, paddingChar: str = "") -> list[list[str]] {

    if padNonFullChunk and len(array) > 0 {
        lastSubArray: list[str] = array[(len(array) - 1)];
        if len(lastSubArray) < chunkNumber {
            for i in range(len(lastSubArray), chunkNumber) {
                lastSubArray = lastSubArray + [paddingChar];
            }
            array[(len(array) - 1)] = lastSubArray;
        }
    }
    return array;
}

