def:pub canvasSetCenter(params: CanvasSetCenterParams) -> None {
    canvas = params.canvas;
    context = params.context;
    canvasWorkingSize = params.canvasWorkingSize;
    setScrollPosition = params.setScrollPosition;
    setZoom = params.setZoom;
    if not canvas or not context {
        return;
    }
    widthOverflow = canvasWorkingSize.width - window.innerWidth;

    heightOverflow = canvasWorkingSize.height - window.innerHeight;
    maxOverflow = Math.max(widthOverflow, heightOverflow);
    hasOverflow = maxOverflow > 0;
    gteMd = window.innerWidth > theme.medias.md;
    gutterTop = 40 if gteMd else 15;
    gutterBottom = 200 if gteMd else 190;
    gutterHorizontal = 200 if gteMd else 24;
    if widthOverflow == maxOverflow {
        newZoom = ((window.innerWidth - gutterHorizontal * 2) / canvasWorkingSize.width) * 100;
    } else {
        newZoom = ((window.innerHeight - gutterTop - gutterBottom) / canvasWorkingSize.height) * 100;
    }
    setZoom(newZoom if hasOverflow else 100);
    scrollPositionX = (window.innerWidth - canvasWorkingSize.width) / 2;
    scrollPositionY = (window.innerHeight - canvasWorkingSize.height) / 2;
    setScrollPosition({"x": scrollPositionX, "y": scrollPositionY + gutterTop});
