def:pub ColorPicker(
    value: str | None = None,
    onChange: Callable[[str], None] | None = None,
    canChangeColor: bool = True,
    style: dict[str, object] = {},
    className: str = "",
) -> JsxElement {
    color = value;

    def onColorChange(newColor: dict[str, object]) {
        rgb = newColor["rgb"] as dict[str, float];
        alpha = 1 if (color is None or _.lowerCase(color) == "transparent") else rgb["a"];
        if onChange {
            onChange(f"rgba({rgb['r']}, {rgb['g']}, {rgb['b']}, {alpha})");
        }
    }

    overlay = (
        <SketchPicker
            color={color}
            className="color-picker-overlay"
            onChangeComplete={onColorChange}
            presetColors={DEFAULT_COLORS}
        />
    );

    <Dropdown overlay={overlay} trigger={["click", "hover"]} disabled={not canChangeColor}>
        <div className={cx("color-picker", className)} style={style}>
            <div className="color-picker-swatch" style={{"backgroundColor": color}} />
        </div>
    </Dropdown>
}
