def find_next_tip(remaining_id_lst: Any, s: Any, s_values: Any) -> object {
    j_nxt = -9999;
    k = 1;
    kmax = len(remaining_id_lst);
    while ((j_nxt < 0) & (k <= kmax)) {
        jj = remaining_id_lst[-k];
