def:pub getThemeBg(theme: bool = True) -> dict[str, str] {
    if theme {
        return {
            "backgroundColor": "rgba(73, 82, 123, 0.3)",
            "color": "rgba(255, 255, 255, 1)"
        };
    }
    return {
        "backgroundColor": "rgba(255, 255, 255, 1)",
        "color": "rgba(0, 0, 0, 1)"
    };
}

def:pub bubbleSort(arr: list[int]) -> Iterator[list[dict[str, int | bool]]] {
    n = len(arr);
    for i = 0 while i < n - 1 with i += 1 {
        for j = 0 while j <= n - i - 1 with j += 1 {
            if arr[j] > arr[j + 1] {
                tmp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = tmp;
            }
            yield [
                {"value": a, "swap": idx == j or idx == j + 1}
                for (idx, a) in enumerate(arr)
            ];
        }
    }
    return arr;
}

def:pub selectionSort(arr: list[int]) -> Iterator[list[dict[str, int | bool]]] {
    n = len(arr);
    for i = 0 while i < n with i += 1 {
        lowest = i;
        for j = i + 1 while j < n with j += 1 {
            if arr[j] < arr[lowest] {
                lowest = j;
            }
        }
        if lowest != i {
            tmp = arr[i];
            arr[i] = arr[lowest];
            arr[lowest] = tmp;
        }
        yield [
            {"value": a, "swap": idx == lowest or idx == i}
            for (idx, a) in enumerate(arr)
        ];
    }
    return arr;
}

def:pub insertionSort(arr: list[int]) -> Iterator[list[dict[str, int | bool]]] {
    n = len(arr);
    for i = 1 while i < n with i += 1 {
        preIndex = i - 1;
        current = arr[i];
        while preIndex >= 0 and arr[preIndex] > current {
            arr[preIndex + 1] = arr[preIndex];
            preIndex -= 1;
        }
        arr[preIndex + 1] = current;
        yield [
            {"value": a, "swap": idx == preIndex + 1 or idx == i}
            for (idx, a) in enumerate(arr)
        ];
    }
    return arr;
}

