      ...oldModel,
      ...newProps,
    }),
    null,
    (): Model => ({
      ...DEFAULT_MODEL,
    })
  );
  const value: [Model, DispatchModelUpdate] = useMemo(() => [model, updateModel], [model, updateModel]);
