"""TB-IR vs v1 whole-record-read parity for nested struct fields."""

node Inner {
    has a: int = 0;
}

node Outer {
    has r: int = 0;
}

node RecordDef {
    has name: str = "";
}

edge NestedField { }
edge DependsOn { }

walker FieldChainResolve {
    has depth: int = 0;
    has leaf_a: int = 0;
    has ok: bool = False;

    can resolve with Outer entry {
        self.depth = 1;
        visit [->:NestedField:->] else { disengage; };
    }

    can at_inner with Inner entry {
        self.depth = 2;
        self.leaf_a = here.a;
        self.ok = True;
        print(f"field chain: o.inner.a={self.leaf_a} depth={self.depth}");
        disengage;
    }
}

walker V1LetBind {
    has copied_a: int = 0;
    has ok: bool = False;

    can attempt with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can whole_read with Inner entry {
        self.copied_a = here.a;
        self.ok = True;
        print(f"v1: let d : Inner = o.inner -> d.a={self.copied_a} PASSED");
        disengage;
    }
}

walker TbirLetBind {
    has ok: bool = False;
    has reason: str = "";

    can attempt with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can reject_bind with Inner entry {
        self.ok = False;
        self.reason = "TB-IR rejects let d : Inner = o.inner";
        print(f"tbir: let d : Inner = o.inner -> REJECTED ({self.reason})");
        disengage;
    }
}

walker FieldCopyRead {
    has captured_a: int = 0;

    can from_outer with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can take with Inner entry {
        self.captured_a = here.a;
        print(f"field read: o.inner.a={self.captured_a}");
        disengage;
    }
}

walker FieldCopyWrite {
    has source_a: int = 0;
    has done: bool = False;

    can into_outer with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can paste with Inner entry {
        here.a = self.source_a;
        self.done = True;
        print(f"field write: p.inner = o.inner -> p.inner.a={here.a}");
        disengage;
    }
}

walker EmitOrder {
    has ordered: bool = False;

    can walk with RecordDef entry {
        if here.name == "Outer" {
            visit [->:DependsOn:->] else { disengage; };
        } elif here.name == "Inner" {
