"""Kitchen line health inspection: probe each station and log every visit.

Two walkers walk the same line — `HealthInspector` flags stations whose
temperature exceeds 40 C, `VisitLogger` records every station visited.
Both checks must run at every station; the union trigger ability on
`Station` lets either walker trigger inspection as it arrives.
"""

node Station {
    has name: str = "";
    has station_type: str = "";
    has celsius: float = 0.0;

    def is_violation() -> bool {
        return self.celsius > 40.0;
    }
}

walker HealthInspector {
    has violations: int = 0;

    can start with Root entry {
        print("HealthInspector walking the line...");
        visit [-->];
    }

    can inspect with Station entry {
        if here.is_violation() {
            self.violations += 1;
            print(f"  [VIOLATION] {here.name} ({here.station_type}) "
                  f"at {here.celsius} C exceeds 40 C");
        } else {
            print(f"  [ok] {here.name} ({here.station_type}) at {here.celsius} C");
        }
        visit [-->];
    }
}

walker VisitLogger {
    has visits: list[str] = [];

    can start with Root entry {
        print("VisitLogger walking the line...");
        visit [-->];
    }

    can log with Station entry {
        self.visits.append(here.name);
        visit [-->];
    }
}

with entry {
    grill = Station(name="Grill", station_type="hot", celsius=180.0);
    fryer = Station(name="Fryer", station_type="hot", celsius=165.0);
    cold_prep = Station(name="ColdPrep", station_type="cold", celsius=45.0);
    walk_in = Station(name="WalkIn", station_type="cold", celsius=3.0);

    root ++> grill ++> fryer ++> cold_prep ++> walk_in;

    inspector = HealthInspector();
    logger = VisitLogger();

    root spawn inspector;
    root spawn logger;

    print(f"Total violations: {inspector.violations}");
    print(f"Stations visited: {logger.visits}");
