"""Rental shop shelf audit.

Books and DVDs are audited through their own typed abilities; anything
else (e.g. an old archive reel) falls through to a union default ability
covering every remaining media type.
"""

node Book {
    has title: str = "";
    has author: str = "";
}

node DVD {
    has title: str = "";
    has runtime: int = 0;
}

node ArchiveReel {
    has title: str = "";
    has format: str = "";
}

walker Auditor {
    has total: int = 0;
    has defaulted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_book with Book entry {
        self.total += 1;
        print(f"Book: '{here.title}' by {here.author}");
        visit [-->];
    }

    can audit_dvd with DVD entry {
        self.total += 1;
        print(f"DVD: '{here.title}' ({here.runtime} min)");
        visit [-->];
    }

    can audit_default with ArchiveReel entry {
        self.total += 1;
        self.defaulted += 1;
        print(f"Default: '{here.title}' [{here.format}]");
        visit [-->];
    }
}

with entry {
    root ++> Book(title="Dune", author="Frank Herbert")
        ++> DVD(title="Blade Runner", runtime=117)
        ++> ArchiveReel(title="Newsreel 42", format="16mm")
        ++> Book(title="Neuromancer", author="William Gibson")
        ++> DVD(title="Arrival", runtime=116);

    auditor = Auditor();
    root spawn auditor;

    print(f"Audited {auditor.total} items; {auditor.defaulted} needed the default path");
}
