"""Review lifecycle atomic-compact-v2 demo.

Models the live review lifecycle from issue #2423:
    candidate consent -> freeze -> admitted lenses
    -> at most one bounded correction
    -> targeted validation -> approval and burn.

Orphaned review surfaces (legacy versions, receipts, lineage,
tombstones, recovery shells) are absent; only the atomic compact-v2
lifecycle remains. A walker traverses the lifecycle stages, guards
against cycles (walker semantics in jac 0.36.1 do not auto-dedupe),
enforces the bounded correction, and burns any approval without
leaving a terminal receipt.
"""

node Candidate {
    has title: str = "";
    has consent_granted: bool = False;
}

node Freeze {
    has freeze_id: str = "";
}

node Lens {
    has reviewer: str = "";
    has admitted: bool = False;
}

node Correction {
    has bounded: bool = True;
    has count: int = 0;
}

node Validation {
    has evidence: str = "";
    has targeted: bool = False;
}

node Approval {
    has final: bool = False;
}

# Typed edges for the live lifecycle steps.
edge ConsentsTo { }
edge FreezesInto { }
edge AdmitsLens { }
edge AllowsCorrection { }
edge TargetsValidation { }
edge ApprovesAndBurns { }

walker LifecycleAuditor {
    # Track visited nodes to enforce no-revisit (jac 0.36.1 walkers
    # do NOT auto-dedupe on cycles, so the policy is explicit).
    has seen: list = [];

    can start with Root entry {
        print("Atomic compact-v2 lifecycle audit starting");
        visit [-->];
    }

    can audit_consent with Candidate entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        status = "consent" if here.consent_granted else "no-consent";
        print(f"[{status}] candidate: {here.title}");
        visit [-->];
    }

    can audit_freeze with Freeze entry {
        print(f"[freeze] freeze_id={here.freeze_id}");
        visit [-->];
    }

    can audit_lenses with Lens entry {
        if not here.admitted {
            print(f"[skip] lens from {here.reviewer} not admitted");
            disengage;
        }
        print(f"[lens] admitted reviewer={here.reviewer}");
        visit [-->];
    }

    can audit_correction with Correction entry {
        # Bounded correction policy: at most one correction per
        # candidate; further attempts terminate the walk.
        if not here.bounded or here.count > 1 {
            print("[refuse] correction not bounded");
            disengage;
        }
        print(f"[correction] bounded, count={here.count}");
        visit [-->];
    }

    can audit_validation with Validation entry {
        if not here.targeted {
            print("[refuse] validation not targeted");
            disengage;
        }
        print(f"[validation] evidence={here.evidence}");
        visit [-->];
    }

    can audit_approval with Approval entry {
        if not here.final {
            print("[refuse] approval not final");
            disengage;
        }
        # Approval leaves no terminal receipt, lineage, witness,
        # or tombstone: just burn and disengage.
        print("[burn] approval final; no receipt retained");
        disengage;
    }
}

