glob SOFT_HYPHEN = re.compile("\u00ad");
glob WHITESPACE = re.compile("\\s+");

def:pub normalizeText(input: str) -> str {
    normalized = unicodedata.normalize("NFKC", input);
    stripped = SOFT_HYPHEN.sub("", normalized);
    lowered = stripped.lower();
    collapsed = WHITESPACE.sub(" ", lowered);
    return collapsed.strip();
}

