def:pub hasMatch(haystack: str, needle: str) -> bool {
    return (len(needle) > 0) and (needle in haystack);
}

def:pub countOccurrences(haystack: str, needle: str) -> int {
    if not needle {
        return 0;
    }
    count = 0;
    from_idx = 0;

    while True {
        at = haystack.find(needle, from_idx);
        if at == -1 {
            return count;
        }
        count = count + 1;
        from_idx = at + len(needle);
    }
}

