def:pub createPalindromeList(input: str, lastChar: bool, multiLine: bool) -> str {
    if not input {
        return "";
    }

    if not multiLine {
        return createPalindrome(input, lastChar);
    }
    array: list[str] = input.split("\n");
    result: list[str] = [];
    for word in array {
        result.append(createPalindrome(word, lastChar));
    }
    return "\n".join(result);
}

