def computeAudioFilter(speed: float) -> str {
    if ((speed <= 2) and (speed >= 0.5)) {
        return f"atempo={speed}";
    }
    filters: list[str] = [];

    remainingSpeed = speed;
    while (remainingSpeed > 2) {
        filters.append("atempo=2.0");
        remainingSpeed /= 2;
    }
    while (remainingSpeed < 0.5) {
        filters.append("atempo=0.5");
