import re;

glob GROUP_ROUTES: set[str] = {"create"};
glob EXPENSE_ROUTES: set[str] = {"create", "export"};

def anonymizePath(path: str) -> str {
    splitMatch: list[str] = re.split(r"(?=[?#])", path);
    pathname: str = splitMatch[0];
    rest: list[str] = splitMatch[1:];
    segments: list[str] = pathname.split("/");
    mapped: list[str] = [];
    for (index, segment) in enumerate(segments) {
        if not segment {
            mapped.append(segment);
        } else {
            parent: str | None = segments[index - 1] if index > 0 else None;

            if parent == "groups" and segment not in GROUP_ROUTES {
                mapped.append("[groupId]");
            } elif parent == "expenses" and segment not in EXPENSE_ROUTES {
                mapped.append("[expenseId]");
            } else {
                mapped.append(segment);
            }
        }
    }
    return "/".join(mapped) + "".join(rest);
}

