import from "history" { createMemoryHistory, createBrowserHistory }

obj HistoryParams {
    has initialEntries: list[str] = [];
}

def createUniversalHistory(params: HistoryParams | None = None) -> object {
    entries: list[str] = [];
    if params is not None {
        entries = params.initialEntries;
    }
    if __BROWSER__ {
        win = window as object;
        cached = win["browserHistory"] if "browserHistory" in win else None;
        history = cached if cached else createBrowserHistory();
        proc = process as object;
        env = proc["env"] as dict[str, str];
        nodeEnv = env["NODE_ENV"] if "NODE_ENV" in env else "";
        if nodeEnv == "development" and not cached {
            win["browserHistory"] = history;
        }
        return history;
    }
    return createMemoryHistory({"initialEntries": entries});
}
