import from types.user { SET, RESET }

glob initialState: dict[str, str] = {"email": "user@example.com"};

obj UserAction {
    has type: str;
    has payload: dict[str, str] | None = None;
}

def reducer(state: dict[str, str] = initialState, action: UserAction) -> dict[str, str] {
    switch action.type {
        case SET:
            if action.payload is not None {
                return {**state, **action.payload};
            }
            return state;
        case RESET:
            return {**initialState};
        default:
            return state;
    }
}
