    has x: float;
    has y: float;
    has r: float;
    has mouseX: float;
    has mouseY: float;
}

def:pub isCursorWithinCircle(params: IsCursorWithinCircleParams) -> bool {
    x = params.x;
    y = params.y;

    r = params.r;
    mouseX = params.mouseX;
    mouseY = params.mouseY;
    distSqr = (x - mouseX) ** 2 + (y - mouseY) ** 2;
    return distSqr < r * r;
