type PropUpdateFn = Callable[[object], None];

def:pub propsUpdater(*updateMaps: object) -> Callable[[dict[str, object]], None] {
    return lambda (changes: dict[str, object]) -> None {
        for updateMap in updateMaps {
            if not isinstance(updateMap, list) {
                mapping = updateMap as dict[str, PropUpdateFn];
                for (prop, updateFn) in mapping.items() {
                    if prop in changes {
                        updateFn(changes[prop]);
                    }
                }
            } else {
                entries = updateMap as list[object];
                mutableObject = entries[0] as dict[str, object];
                for p in entries[1:] {
                    if isinstance(p, dict) {
                        keyMap = p as dict[str, str];
                        for (prop, objectKey) in keyMap.items() {
                            if prop in changes {
                                mutableObject[objectKey] = changes[prop];
                            }
                        }
                    } else {
                        propName = p as str;
                        if propName in changes {
                            mutableObject[propName] = changes[propName];
                        }
                    }
                }
            }
        }
    };
}
