def:pub useBeforeUnload(enabled: bool = True, message: str | None = None) {
    useEffect(lambda {
        if not enabled {
            return;
        }
        handler = lambda (event: Event) {
            event.preventDefault();
            if message {
                (event as dict[str, str])["returnValue"] = message;

            }
            return message;
        };
        window.addEventListener("beforeunload", handler);
        return lambda {
            window.removeEventListener("beforeunload", handler);
        };
    }, [message, enabled]);
}

