import re;
import from math { ceil }

type SplitOperatorType = "symbol" | "regex" | "length" | "chunks";

def splitTextByLength(text: str, length: int) -> list[str] {
    if length <= 0 {
        raise ValueError("Length must be a positive number");
    }
    result: list[str] = [];
    for i = 0 while i < len(text) with i += length {
        result.append(text[i:i + length]);
    }
    return result;
}

def splitIntoChunks(text: str, numChunks: int) -> list[str] {
    if numChunks <= 0 {
        raise ValueError("Number of chunks must be a positive number");
    }
    totalLength = len(text);
    if totalLength < numChunks {
        raise ValueError("Text length must be at least as long as the number of chunks");
    }
    chunkSize = ceil(totalLength / numChunks);
    result: list[str] = [];
    for i = 0 while i < totalLength with i += chunkSize {
        result.append(text[i:i + chunkSize]);
    }
    if len(result) > numChunks {
        result[numChunks - 1] = "".join(result[numChunks - 1:]);
        result = result[0:numChunks];
    }
    return result;
}

def compute(
    splitSeparatorType: SplitOperatorType,
    input: str,
    symbolValue: str,
    regexValue: str,
    lengthValue: int,
    chunksValue: int,
    charBeforeChunk: str,
    charAfterChunk: str,
    outputSeparator: str
) -> str {
    splitText: list[str] = [];
    switch splitSeparatorType {
        case "symbol":
            splitText = input.split(symbolValue);
            break;
        case "regex":
            splitText = re.split(regexValue, input);
            break;
        case "length":
            splitText = splitTextByLength(input, lengthValue);
            break;
        case "chunks":
            splitText = [
                f"{charBeforeChunk}{chunk}{charAfterChunk}"
                for chunk in splitIntoChunks(input, chunksValue)
            ];
            break;
        default:
            break;
    }
    return outputSeparator.join(splitText);
}
