obj ModelsStore {
    has models: modelsType = [];

    def setModels(modelInfo: modelInfoType, model: object, editorId: int) {
        existingIndex = -1;
        for i = 0 while i < len(self.models) with i += 1 {
            if self.models[i].id == modelInfo.id {
                existingIndex = i;
                break;
            }
        }
        if existingIndex == -1 {
            self.models = self.models + [modelType(
                filename=modelInfo.filename,
                language=modelInfo.language,
                value=modelInfo.value,
                id=modelInfo.id,
                model=model,
                usedBy=[editorId]
            )];
        } elif editorId in self.models[existingIndex].usedBy {
            return;
        } else {
            updated = list(self.models);
            updated[existingIndex].usedBy = updated[existingIndex].usedBy + [editorId];
            self.models = updated;
        }
    }

    def removeModel(id: str, editorId: int) -> modelsType {

    updated: modelsType = [];
    for m in self.models {
        if m.id == id {
            remaining = [e for e in m.usedBy if e != editorId];
            if len(remaining) > 0 {
                updated.append(modelType(
                    filename=m.filename,
                    language=m.language,
                    value=m.value,
                    id=m.id,
                    model=m.model,
                    usedBy=remaining
                ));
            }
        } else {
            updated.append(m);
        }
    }
    self.models = updated;
    return self.models;
}

