import from "@utils/string" { unquoteIfQuoted }

def:pub csvToTsv(input: str, delimiter: str, quoteCharacter: str, commentCharacter: str, header: bool, emptyLines: bool) -> str {
    if not input {
        return "";
    }
    lines = input.split("\n");
    if not header and len(lines) > 0 {
        lines = lines[1:];
    }
    tsvLines: list[str] = [];
    for line in lines {

        if commentCharacter and line.startswith(commentCharacter) {
            tsvLines.append("");
            continue;
        }
        cells = line.split(delimiter);
        for index in range(len(cells)) {
            cells[index] = unquoteIfQuoted(cells[index], quoteCharacter);
        }
        tsvLines.append("\t".join(cells));
    }
    if not emptyLines {
        return "\n".join(tsvLines);
    }
    return "\n".join([line for line in tsvLines if line.strip() != ""]);
}

