glob UPPER_I: int = byteOf("I");
glob UPPER_D: int = byteOf("D");
glob UPPER_E: int = byteOf("E");

def isImageDataMarker(data: bytes, p: int) -> bool {
    if data[p] != UPPER_I or data[p + 1] != UPPER_D or p == 0 {
        return False;
    }
    before = data[p - 1];

    if isRegular(before) or before == SLASH {
        return False;
    }
    after = data[p + 2] if p + 2 < len(data) else None;
    return after is None or isWhitespace(after);
}

