"""Daily student attendance: register unit, calendar, and mark traversal.

Models the essential graph machinery from sis-v2 wayfinder ticket #111:
class register units, attendance marks keyed on (student, date), and a
calendar that voids closures. A walker walks the day's register,
applies the closure rule, and computes a per-class summary while
honouring the locked decisions (manual entry, late counts as present,
edit window, calendar is load-bearing).
"""

node Campus {
    has name: str = "";
}

node StandardLevel {
    has name: str = "";
}

node AcademicYear {
    has label: str = "";
}

edge BelongsTo {}

node Register {
    has level_name: str = "";
    has campus_name: str = "";
    has year_label: str = "";
    # Whether the class unit has any marks yet — used by the closure
    # confirmation rule.
    has has_marks: bool = False;
}

edge Enrolled {}

node Student {
    has name: str = "";
}

node AttendanceMark {
    has status: str = "";
    has marked_by: str = "";
    # Status as a judgement: "present" / "absent" / "late".
    has counts_as_present: bool = True;
    has date: str = "";
}

edge MarkedOn {
    has date: str = "";
}

node CalendarDay {
    has date: str = "";
    has is_school_day: bool = True;
    # Closed days (hartal/flood/unrest) void the date entirely.
    has is_closed: bool = False;
}

edge Calendar {}

walker AttendanceAuditor {
    has target_date: str = "";
    has present_total: int = 0;
    has absent_total: int = 0;
    has unmarked_school_days: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_register with Register entry {
        if here.has_marks {
            print(f"register {here.level_name}/{here.campus_name}/{here.year_label}: scanning marks");
        } else {
            print(f"register {here.level_name}/{here.campus_name}/{here.year_label}: no marks yet");
        }
        visit [-->];
    }

    can audit_student with Student entry {
        visit [-->];
    }

    can tally_mark with AttendanceMark entry {
        # Locked #111: late counts as present for the percentage.
        if here.counts_as_present {
            self.present_total += 1;
        } else {
            self.absent_total += 1;
        }
        # No visit: marks are leaves on the (student, date) edge.
    }

    can audit_calendar with CalendarDay entry {
        # Closed days void the date entirely — they are excluded from the
        # denominator. Unmarked school days are surfaced for chase.
        if here.is_closed {
            print(f"calendar {here.date}: CLOSED (voided, not in figure)");
        } elif not here.is_school_day {
            print(f"calendar {here.date}: non-school day");
        } else {
            self.unmarked_school_days.append(here.date);
            print(f"calendar {here.date}: unmarked school day (chase)");
        }
        visit [-->];
    }
}

with entry {
    # Campus + level topology.
    dhaka = Campus(name="Dhaka");
    chittagong = Campus(name="Chittagong");
    root ++> dhaka ++> chittagong;

    primary = StandardLevel(name="Grade 3");
    root ++> primary;

    # Academic year envelope.
    year = AcademicYear(label="2026");
    root ++> year;

    # Register units = (standardLevel, academicYear, campus). No section,
    # per ticket #112.
    reg_dhaka = Register(
        level_name="Grade 3",
        campus_name="Dhaka",
        year_label="2026",
        has_marks=True,
    );
    reg_ctg = Register(
        level_name="Grade 3",
        campus_name="Chittagong",
        year_label="2026",
        has_marks=True,
    );
    dhaka +>:BelongsTo:+> reg_dhaka;
    chittagong +>:BelongsTo:+> reg_ctg;
    primary +>:BelongsTo:+> reg_dhaka;
    primary +>:BelongsTo:+> reg_ctg;
    year +>:BelongsTo:+> reg_dhaka;
    year +>:BelongsTo:+> reg_ctg;

    # Students enrolled in each register.
    aisha = Student(name="Aisha");
    bobby = Student(name="Bobby");
    camila = Student(name="Camila");
    danish = Student(name="Danish");
    reg_dhaka +>:Enrolled:+> aisha;
    reg_dhaka +>:Enrolled:+> bobby;
    reg_ctg +>:Enrolled:+> camila;
    reg_ctg +>:Enrolled:+> danish;

    # Today's marks (manual entry, last-writer-wins on (studentId, date)).
    today = "2026-03-04";
    a_mark = AttendanceMark(
        status="present",
        marked_by="teacher-7",
        counts_as_present=True,
        date=today,
    );
    b_mark = AttendanceMark(
        status="late",
        marked_by="teacher-7",
        counts_as_present=True,
        date=today,
    );
    c_mark = AttendanceMark(
        status="absent",
        marked_by="teacher-12",
        counts_as_present=False,
        date=today,
    );
    d_mark = AttendanceMark(
        status="present",
        marked_by="teacher-12",
        counts_as_present=True,
        date=today,
    );
    aisha +>:MarkedOn(date=today):+> a_mark;
    bobby +>:MarkedOn(date=today):+> b_mark;
    camila +>:MarkedOn(date=today):+> c_mark;
    danish +>:MarkedOn(date=today):+> d_mark;

    # Calendar: today is a school day with a future closure flagged.
    day_open = CalendarDay(date="2026-03-04", is_school_day=True, is_closed=False);
    day_closed = CalendarDay(date="2026-03-05", is_school_day=True, is_closed=True);
    day_weekend = CalendarDay(date="2026-03-06", is_school_day=False, is_closed=False);
    root +>:Calendar:+> day_open;
    root +>:Calendar:+> day_closed;
    root +>:Calendar:+> day_weekend;

    auditor = AttendanceAuditor(target_date=today);
    root spawn auditor;

    print(f"figure: present={auditor.present_total}, absent={auditor.absent_total}");
    print(f"chase list (unmarked school days): {auditor.unmarked_school_days}");
}
