def:pub loadState(key: str) -> object | None {
    try {
        serializedState = localStorage.getItem(key);
        if serializedState is None {
            return None;
        }
        return JSON.parse(serializedState) as object;
    } except Exception as e {
        return e as object;
    }
}

def:pub saveState(key: str, value: str) -> object | None {

    try {
        localStorage.setItem(key, JSON.stringify(value));
        return None;
    } except Exception as e {
        return e as object;
    }
}

