"""Cycle-safe JSON field collector.

Models the `collectJSONFields` helper from go-hooppy issue #123, where
recursing into self-referential embedded structs caused a stack overflow
instead of a proper diagnostic. The fix threads a visited set through the
walk so a type already on the path is skipped, mirroring what
`encoding/json`'s `typeFields` does.

The walker below is the idiomatic Jac equivalent: a `FieldCollector`
walker traverses embedded-field edges through the type graph, accumulating
field names on a single typed `has` accumulator. Without the visited set
the walker would loop forever on cyclic graphs (jac 0.36.1 has no
built-in once-per-node visitation), exactly matching the original bug.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node GoType {
    has name: str = "";
    has fields: list[str] = [];

    def describe() -> str {
        return f"{self.name}={self.fields}";
    }
}

# A concrete struct type with a list of (field_name, embedded_type_name)
# pairs. embedded targets are resolved via `Embeds` typed edges so the
# graph is the relationship, not a string lookup.
node StructType(GoType) {
    has embeds: list[str] = [];

    override def describe() -> str {
        return f"struct {self.name} embeds={self.embeds} fields={self.fields}";
    }
}

# ---------------------------------------------------------------------------
# Relationship: "struct X embeds struct Y by name"
# ---------------------------------------------------------------------------

edge Embeds { has since: str = "v1"; }

# ---------------------------------------------------------------------------
# Walker: cycle-safe JSON field collector
# ---------------------------------------------------------------------------

walker FieldCollector {
    has visited: list[GoType] = [];
    has collected: list[str] = [];

    def already_seen(t: GoType) -> bool {

    for v in self.visited {
        if v.name == t.name {
            return True;
        }
    }
    return False;
}

