import from "io-ts" { Type, success, failure }
import from ..statusCode { StatusCodeMap, statusPredicate }
import type from ..statusCode { StatusCode }

def allStatusPredicate(u: object) -> bool {
    return statusPredicate(StatusCodeMap)(u);
}

def allStatusPredicateWithZero(u: object) -> bool {
    return allStatusPredicate(u) or u == 0;
}

def decodeStatusCode(u: object, c: object) -> object {
    if allStatusPredicate(u) {
        return success(u);
    }
    return failure(u, c);
}

def decodeStatusCodeWithZero(u: object, c: object) -> object {
    if allStatusPredicateWithZero(u) {
        return success(u);
    }
    return failure(u, c);
}

type StatusCodeC = Type[StatusCode, str | int, object];

