def interweave(array1: list[str], array2: list[str]) -> list[str] {
    result: list[str] = [];
    maxLength = max(len(array1), len(array2));
    for i = 0 while i < maxLength with i += 1 {
        if i < len(array1) {
            result.append(array1[i]);
        }
        if i < len(array2) {
            result.append(array2[i]);
        }
    }
    return result;
}

def duplicate(input: list[str], concatenate: bool, reverse: bool, copy: float | None = None) -> list[str] {

    if copy is None {
        raise ValueError("Number of copies must be a valid number");
    }
    if copy <= 0 {
        raise ValueError("Number of copies cannot be negative");
    }
    whole = int(copy // 1);
    fractional = copy - whole;
    WholePart: list[str] = [];
    fractionalPart: list[str] = [];
    toAdd: list[str] = [];
    result: list[str] = [];
    if not reverse {
        if concatenate {
            WholePart = [item for _ in range(whole) for item in input];
        } else {
            WholePart = [item for _ in range(whole - 1) for item in input];
        }
        fractionalPart = input[0:int(len(input) * fractional)];
        toAdd = WholePart + fractionalPart;
        result = (WholePart + fractionalPart) if concatenate else interweave(input, toAdd);
    } else {
        WholePart = list(reversed([item for _ in range(whole - 1) for item in input]));
        fractionalPart = list(reversed(input))[0:int(len(input) * fractional)];
        toAdd = WholePart + fractionalPart;
        result = (input + toAdd) if concatenate else interweave(input, toAdd);
    }
    return result;
}

