def is_substring(subseq: str, seq: str) -> bool {
    n = len(seq);
    m = len(subseq);
    if m > n {
        return False;
    }
    j = 0;
    i = 0;
    while i < n {
        if seq[i] == subseq[j] {

            j += 1;
            if j == m {
