import from "d3-ease" { easeQuadInOut }
import from "valtio" { useSnapshot }
import from "./state" { state }

type TransformDict = dict[str, str];
type AnimationDict = dict[str, TransformDict];

glob floatAnimations: dict[str, AnimationDict] = {
    "float": {
        "from": {"transform": "translate3d(0, 0px, 0)"},
        "to": {"transform": "translate3d(0, -20px, 0)"},
    },
    "float-mid": {
        "from": {"transform": "translate3d(0, 0px, 0)"},
        "to": {"transform": "translate3d(0, -40px, 0)"},
    },
    "float-rotate-mid": {
        "from": {"transform": "translate3d(0, -50px, 0) rotate(0deg)"},
        "to": {"transform": "translate3d(0, 0px, 0) rotate(180deg)"},
    },
    "float-hi": {
        "from": {"transform": "translate3d(0, 0px, 0)"},
        "to": {"transform": "translate3d(0, -60px, 0)"},
    },
};

def clamp(num: float, min_val: float, max_val: float) -> float {
    return min(max(num, min_val), max_val);
}

def useFloatAnimation(animation: str, offset: float = 0.0) -> TransformDict {
    snap = useSnapshot(state);
    anim = floatAnimations[animation];
    from_val = anim["from"];
    to_val = anim["to"];
    return useSpring({
        "config": {
            "duration": clamp(snap.dur * 1000.0 + offset, 500.0, 10000.0),
            "easing": easeQuadInOut,
        },

        "from": from_val,
        "to": lambda (advance: Callable[[TransformDict], Awaitable[None]]) {
            async def run_loop() {
                while True {
                    await advance(to_val);
                    await advance(from_val);
                }
            }
            run_loop();
        },
    });
}

