  var SKIP = {{{SKIP_OBJECT_LITERAL}}};
  if (!document.body) return {{ results: [], total: 0 }};
  var els = document.body.querySelectorAll('*');
  var total = els.length;
  var end = Math.min(offset + limit, total);
  var results = [];
  for (var i = offset; i < end; i++) {{
