    roman_number = "";
    for (index, digit) in enumerate(reversed(str(number))) {
        if index == 0 {
            first = "I";
            fifth = "V";
            tenth = "X";
        } elif index == 1 {
            first = "X";
            fifth = "L";
            tenth = "C";
        } elif index == 2 {
            first = "C";
            fifth = "D";
            tenth = "M";
        } elif index == 3 {
            first = "M";
            fifth = "";
            tenth = "";
