def itemCounter(items: list[str], ignoreCase: bool) -> dict[str, int] {
    counts: dict[str, int] = {};
    for item in items {
        key = item.lower() if ignoreCase else item;
        counts[key] = counts.get(key, 0) + 1;
    }
    return counts;
}

def dictSorter(dict: dict[str, int], sortingMethod: SortingMethod) -> dict[str, int] {
    sortedArray: list[tuple[str, int]];
    if sortingMethod == "count" {
        sortedArray = sorted(
            dict.items(),
            key=lambda (kv: tuple[str, int]) { kv[1]; },
            reverse=True,
        );
    }
    elif sortingMethod == "alphabetic" {
        sortedArray = sorted(dict.items(), key=lambda (kv: tuple[str, int]) { kv[0]; });
    }
    else {
        sortedArray = list(dict.items());
    }
    return dict(sortedArray);
}

def displayFormater(dict: dict[str, int], displayFormat: DisplayFormat) -> list[str] {
    formattedOutput: list[str] = [];
    total = sum(dict.values());
    for (key, value) in dict.items() {
        if displayFormat == "percentage" {
            formattedOutput.append(f"{key}: {value} ({((value / total) * 100):.2f}%)");
        }
        elif displayFormat == "total" {
            formattedOutput.append(f"{key}: {value} ({value} / {total})");

        }
        elif displayFormat == "count" {
            formattedOutput.append(f"{key}: {value}");
        }
    }
    return formattedOutput;
}

