                % lockRet['Counts']['Success']
            )
        );
        compStr = ','.join(lockRet['Success']['ComponentIDs']);

        print(("    " + compStr));
    }
    if (lockRet['Counts']['Failure'] > 0) {
        print(
            (
                "Failed to lock %d management nodes and BMCs:"
                % lockRet['Counts']['Failure']
            )
        );
        for comp in lockRet['Failure'] {
