def:pub convertHoursToDays(input: str, accuracy: str, daysFlag: bool) -> str {
    if not containsOnlyDigits(accuracy) {
        raise ValueError("Accuracy contains non digits.");
    }
    result: list[str] = [];
    lines = input.split("\n");
    accuracy_num = int(accuracy);

    for line in lines {
        parts = line.split(" ");
        hours = parts[0];
        days = compute(hours, accuracy_num);
        if daysFlag {
            result.append(f"{days} days");
        } else {
            result.append(f"{days}");
        }
    }
    return "\n".join(result);
