import re;
import from .parseAbbrValue { parseAbbrValue }
import from .removeSeparators { removeSeparators }
import from .removeInvalidChars { removeInvalidChars }
import from .escapeRegExp { escapeRegExp }

type CleanValueTransform = Callable[[str], str];

obj CleanValueOptions {
    has value: str;
    has groupSeparator: str = ",";
    has decimalSeparator: str = ".";
    has allowDecimals: bool = True;
    has decimalsLimit: int = 2;
    has allowNegativeValue: bool = True;
    has disableAbbreviations: bool = False;
    has prefix: str = "";
    has transformRawValue: CleanValueTransform | None = None;
}

def identityTransform(rawValue: str) -> str {
    return rawValue;
}

def:pub cleanValue(options: CleanValueOptions) -> str {

    value = options.value;
    groupSeparator = options.groupSeparator;
    decimalSeparator = options.decimalSeparator;
    allowDecimals = options.allowDecimals;
    decimalsLimit = options.decimalsLimit;
    allowNegativeValue = options.allowNegativeValue;
    disableAbbreviations = options.disableAbbreviations;
    prefix = options.prefix;
    transformRawValue: CleanValueTransform = identityTransform;
    if options.transformRawValue is not None {
        transformRawValue = options.transformRawValue;
    }
    transformedValue: str = transformRawValue(value);

    if transformedValue == "-" {
        return transformedValue;
    }

    abbreviations: list[str] = [] if disableAbbreviations else ["k", "m", "b"];
    negPattern = f"((^|\\D)-\\d)|(-{escapeRegExp(prefix)})";
    isNegative = re.search(negPattern, transformedValue) is not None;

    prefixPattern = f"(\\d+)-?{escapeRegExp(prefix)}";
    prefixMatch = re.search(prefixPattern, value);
    prefixWithValue = "";
    preValue = "";
    if prefixMatch is not None {
        prefixWithValue = prefixMatch.group(0);
        preValue = prefixMatch.group(1);
    }

    withoutPrefix: str = transformedValue;
    if prefix {
        if prefixWithValue {
            withoutPrefix = transformedValue.replace(prefixWithValue, "") + preValue;
        } else {
            withoutPrefix = transformedValue.replace(prefix, "");
        }
    }

    withoutSeparators = removeSeparators(withoutPrefix, groupSeparator);
    withoutInvalidChars = removeInvalidChars(
        withoutSeparators,
        [groupSeparator, decimalSeparator] + abbreviations
    );

    valueOnly: str = withoutInvalidChars;

    if not disableAbbreviations {
        lowered = withoutInvalidChars.lower().replace(decimalSeparator, "");
        for letter in abbreviations {
            if letter == lowered {
                return "";
            }
        }
        parsed = parseAbbrValue(withoutInvalidChars, decimalSeparator);
        if parsed {
            valueOnly = str(parsed);
        }
    }

    includeNegative = "-" if (isNegative and allowNegativeValue) else "";

    if decimalSeparator and decimalSeparator in valueOnly {
        parts = withoutInvalidChars.split(decimalSeparator);
        intPart = parts[0];
        decimals = parts[1] if len(parts) > 1 else "";
        trimmedDecimals = decimals[:decimalsLimit] if (decimalsLimit and decimals) else decimals;
        includeDecimals = f"{decimalSeparator}{trimmedDecimals}" if allowDecimals else "";
        return f"{includeNegative}{intPart}{includeDecimals}";
    }

    return f"{includeNegative}{valueOnly}";
}

