import from react { useEffect }

def isFocusedElementEditable() -> bool {
    activeElement = document.activeElement as HTMLElement | None;
    body = document.body;
    if activeElement is None {
        return False;
    }
    if activeElement is body {
        return False;
    }
    match activeElement.tagName {
        case "INPUT":
            return True;
        case "TEXTAREA":
            return True;
        case _:
            return activeElement.hasAttribute("contenteditable");
    }
}

def isTypedCharGood(event: KeyboardEvent) -> bool {
    if event.metaKey or event.ctrlKey or event.altKey {
        return False;
    }
    key = event.key;
    if len(key) != 1 {
        return False;
    }
    ch = key[0];
    if ch.isdigit() {
        return True;
    }
    if (ch >= "A") and (ch <= "Z") {
        return True;
    }
    return False;
}

def useStartTyping(onStartTyping: Callable[[KeyboardEvent], None]) {
    useEffect(lambda {
        def keydown(event: KeyboardEvent) {
            if (not isFocusedElementEditable()) and isTypedCharGood(event) {

                onStartTyping(event);
            }
        }
        document.addEventListener("keydown", keydown);
        return lambda {
            document.removeEventListener("keydown", keydown);
        };
    }, []);
}

