import from difflib { SequenceMatcher }

glob RATING_MINIMUM: float = 0.2;

type RateCandidate = tuple[float, str, str];
type MakeColor = Callable[[str, str | None], str];

obj TailwindConfig {
    has theme: dict[str, object] = {};
    has separator: str | None = None;
}

obj TailwindMatch {}

obj TailwindContext {
    has candidateRuleMap: list[tuple[str, list[TailwindMatch]]] = [];
    has variantMap: list[tuple[str, dict[str, object]]] = [];
}

obj ClassErrorContext {
    has color: MakeColor;
    has candidates: set[tuple[str, list[list[dict[str, object]]]]];
    has variants: set[str];
    has tailwindConfig: TailwindConfig;
    has tailwindContext: TailwindContext;
    has CustomError: type[Exception];
    has suggestionNumber: int = 4;
}

def compareTwoStrings(a: str, b: str) -> float {
    return SequenceMatcher(None, a, b).ratio();
}

def rateCandidate(classData: tuple[str, object], className: str, matchee: str) -> RateCandidate | None {
    (classEnd, value) = classData;
    parts = [className, "" if classEnd == "DEFAULT" else classEnd];
    candidate = "-".join([p for p in parts if p]);
    rating = float(compareTwoStrings(matchee, candidate));
    if rating < RATING_MINIMUM {
        return None;
    }
    classValueRaw: str;
    if isinstance(value, str) {
        classValueRaw = "''" if len(value) == 0 else value;
    } elif isinstance(value, list) {
        classValueRaw = ", ".join([str(v) for v in value]);
    } else {
        classValueRaw = str(value);
    }
    classValue = classValueRaw + (" (DEFAULT)" if classEnd == "DEFAULT" else "");
    return (rating, candidate, classValue);
}

def extractCandidates(
    candidates: set[tuple[str, list[list[dict[str, object]]]]],
    matchee: str
) -> list[RateCandidate] {
    results: list[RateCandidate] = [];
    for (className, classOptionSet) in candidates {
        for classOption in classOptionSet {
            optionHead = classOption[0];
            options = optionHead.get("options") if isinstance(optionHead, dict) else None;
            if options is not None and isinstance(options, dict) {
                values = options.get("values");
                if values is not None and isinstance(values, dict) {
                    for valueEntry in values.items() {
                        rated = rateCandidate(valueEntry, className, matchee);
                        if rated is not None {
                            results.append(rated);
                        }
                    }
                }
            } else {
                rated = rateCandidate(("", className), className, matchee);
                if rated is not None {
                    results.append(rated);
                }
            }
        }
    }
    return results;
}

def getClassSuggestions(matchee: str, context: ClassErrorContext) -> str {

    color = context.color;
    candidates = extractCandidates(context.candidates, matchee);
    inner = context.color(matchee, "errorLight");
    errorText = context.color(f"✕ {inner} was not found", "error");
    if len(candidates) == 0 {
        return errorText;
    }
    candidates = sorted(candidates, key=lambda (item: RateCandidate) { return item[0]; }, reverse=True);
    firstSuggestion = candidates[0];
    secondSuggestion: RateCandidate | list[object] = candidates[1] if len(candidates) > 1 else [];
    (firstRating, firstCandidate, firstClassValue) = firstSuggestion;
    secondRating = secondSuggestion[0] if isinstance(secondSuggestion, tuple) else 0.0;
    hasWinningSuggestion = (
        isinstance(secondSuggestion, tuple) and firstRating - secondRating > 0.12
    );
    if len(candidates) == 1 or hasWinningSuggestion {
        valueText = "" if firstClassValue == firstCandidate else f" ({firstClassValue})";
        return "\n\n".join([
            errorText,
            f"Did you mean {color(firstCandidate, 'success')} ?{valueText}",
        ]);
    }
    suggestions = [
        f"{color('-', 'subdued')} {color(suggestion, 'highlight')} "
        + ("" if value == "false" else f"{color('>', 'subdued')} {value}")
        for (_, suggestion, value) in candidates[: context.suggestionNumber]
    ];
    return "\n\n".join([errorText, "Try one of these classes:", "\n".join(suggestions)]);
}

