          extension={'pdf'}
          loading={isProcessing}
          loadingText={t('rotatePdf.rotatingPages')}
        />
      }
      getGroups={({ values, updateField }) => [
        {
          title: t('rotatePdf.rotationSettings'),
          component: (
            <Box>
