def:pub useEscapeKey(handleClose: Callable[[], None]) {
    useEffect(lambda {
        def handle_esc(event: KeyboardEvent) {
            if event.key == KEY_NAME_ESC {
                handleClose();
            }

        }
        document.addEventListener(KEY_EVENT_TYPE, handle_esc, False);
