import json;

def:pub decycle(object: object, replacer: Callable[[object], object] | None = None) -> object {

    objects: dict[int, str] = {};

    def derez(value: object, path: str) -> object {
        if replacer is not None {
            value = replacer(value);
        }
        if (
            (isinstance(value, dict) or isinstance(value, list))
            and value is not None
        ) {
            old_path = objects.get(id(value));
            if old_path is not None {
                return {"$ref": old_path};
            }
            objects[id(value)] = path;
            if isinstance(value, list) {
                new_item: list[object] = [];
                for (i, element) in enumerate(value) {
                    new_item.append(derez(element, path + f"[{i}]"));
                }
                return new_item;
            }
            new_item: dict[str, object] = {};
            for name in value.keys() {
                new_item[name] = derez(
                    value[name],
                    path + f"[{json.dumps(name)}]"
                );
            }
            return new_item;
        }
        return value;
    }

    return derez(object, "$");
}

