"""Hiking trail: chain waypoints from trailhead to summit; hiker counts each stop."""

node TrailStop {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Trailhead(TrailStop) { }

node Waypoint(TrailStop) { }

node Summit(TrailStop) { }

walker Hiker {
    has stop_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hike with Trailhead | Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->];
    }

    can finish with Summit entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        print(f"Trail complete: passed {self.stop_count} stops.");
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    root spawn Hiker();
}
