def splitCsvLine(line: str, delimiter: str = ",", quoteChar: str = "\"") -> list[str] {
    result: list[str] = [];
    current = "";
    inQuotes = False;
    for i = 0 while i < len(line) with i += 1 {
        char = line[i];
        nextChar = line[i + 1] if (i + 1) < len(line) else "";
        if char == quoteChar {
            if inQuotes and nextChar == quoteChar {
                current += quoteChar;
                i += 1;
            } else {
                inQuotes = not inQuotes;
            }
        } elif char == delimiter and not inQuotes {
            result.append(current.strip());
            current = "";
        } else {
            current += char;
        }
    }
    result.append(current.strip());
    return result;
}

def:pub splitCsv(input: str, deleteComment: bool, commentCharacter: str, deleteEmptyLines: bool, delimiter: str = ",", quoteChar: str = "\"") -> list[list[str]] {
