    if deleteComment and commentCharacter {
        rows = [row for row in rows if not row[0].strip().startswith(commentCharacter)];
    }

    if deleteEmptyLines {
        rows = [row for row in rows if any(cell.strip() != "" for cell in row)];
    }
    return rows;
}

