import type from core.types { AssertContext }
import from core.lib.logging { makeColor }

type AssertFn = Callable[[bool | str | Callable[[AssertContext], str], str | Callable[[AssertContext], str]], None];

def createAssert(
    isSilent: bool = False,
    hasLogColors: bool = True,
) -> AssertFn {
    def assertImpl(
        expression: bool | str | Callable[[AssertContext], str],
        message: str | Callable[[AssertContext], str],
    ) -> None {
        if isSilent {
            return;
        }
        if isinstance(expression, str) {
            raise Exception(f"\n\n{expression}\n");
        }
        messageContext = AssertContext(color=makeColor(hasLogColors));
        if callable(expression) {
            raise Exception(f"\n\n{expression(messageContext)}\n");
        }
        if expression {
            return;
        }
        if isinstance(message, str) {
            raise Exception(f"\n\n{message}\n");
        }
        if callable(message) {
            raise Exception(f"\n\n{message(messageContext)}\n");
        }
    }
    return assertImpl;
}
