import from "react" { useEffect, useState }

def:pub useGeolocation() -> dict[str, object] {
    statePair = useState({
        "loading": True,
        "accuracy": None,
        "altitude": None,
        "altitudeAccuracy": None,
        "heading": None,
        "latitude": None,
        "longitude": None,
        "speed": None,
        "timestamp": Date.now(),
    });
    state = statePair[0];
    setState = statePair[1];
    mounted = True;
    watchId = 0;
    geo = getattr(navigator, "geolocation");

    onEvent = lambda (event: object) -> None {
        if mounted {
            coords = getattr(event, "coords");
            setState({
                "loading": False,
                "accuracy": getattr(coords, "accuracy"),
                "altitude": getattr(coords, "altitude"),
                "altitudeAccuracy": getattr(coords, "altitudeAccuracy"),
                "heading": getattr(coords, "heading"),
                "latitude": getattr(coords, "latitude"),
                "longitude": getattr(coords, "longitude"),
                "speed": getattr(coords, "speed"),
                "timestamp": getattr(event, "timestamp"),
            });
        }
    };

    onEventError = lambda (error: object) -> None {
        if mounted {
            setState(lambda (oldState: dict[str, object]) -> dict[str, object] {
                return {**oldState, "loading": False, "error": error};
            });
        }
    };

    useEffect(lambda {
        geo.getCurrentPosition(onEvent, onEventError);
        watchId = geo.watchPosition(onEvent, onEventError);
        return lambda {
            mounted = False;
            geo.clearWatch(watchId);
        };
    }, []);

    return state as dict[str, object];
}
