def reducer(state: AuthState, action: dict[str, object]) -> AuthState {
    action_type = action["type"] as str;
    match action_type {
        case "LOGIN_POPUP_STARTED":
            return AuthState(
                isLoading=True,
                isAuthenticated=state.isAuthenticated,
                user=state.user,
                error=state.error,
            );
        case "LOGIN_POPUP_COMPLETE" | "INITIALISED":
            user = action["user"] as User | None;
            return AuthState(
                isLoading=False,
                isAuthenticated=user is not None,
                user=user,
                error=None,
            );
        case "HANDLE_REDIRECT_COMPLETE" | "GET_ACCESS_TOKEN_COMPLETE" | "SYNC_USER":
            user = action["user"] as User | None;
            if state.user == user {
                return state;
            }
            return AuthState(
                isLoading=state.isLoading,
                isAuthenticated=user is not None,
                user=user,
                error=state.error,
            );

        case "LOGOUT":
            return AuthState(
                isLoading=state.isLoading,
                isAuthenticated=False,
                user=None,
                error=state.error,
            );
        case "ERROR":
            err = action["error"] as Exception;
            return AuthState(
                isLoading=False,
                isAuthenticated=state.isAuthenticated,
                user=state.user,
                error=err,
            );
        case _:
            return state;
    }
}

