import re;

type SplitOperatorType = "symbol" | "regex";

def:pub reverseList(
    splitOperatorType: SplitOperatorType,
    splitSeparator: str,
    joinSeparator: str = "\n",
    input: str,
) -> str {
    array: list[str] = [];
    if splitOperatorType == "symbol" {
        array = input.split(splitSeparator);
    }
    elif splitOperatorType == "regex" {
        array = [item for item in re.split(splitSeparator, input) if item != ""];
    }
    reversedList = list(reversed(array));
    return joinSeparator.join(reversedList);
}
