type PackageManagerContextValue = {
    selectedPackageManager: PackageManager,
    setPackageManager: Callable[[PackageManager], None],
    isHydrated: bool,
};

glob STORAGE_KEY: str = "package-manager";

def _noopPackageManager(_: PackageManager) {}

def getStoredPackageManager() -> PackageManager {
    try {
        stored = localStorage.getItem(STORAGE_KEY);
        if stored and stored in packageManagers {
            return stored as PackageManager;
        }
        setStoredPackageManager("pnpm");
    } except Exception as error {
        console.warn("Failed to read package manager from localStorage:", error);
    }
    return "pnpm";
}

def setStoredPackageManager(packageManager: PackageManager) {
    if not window {
        return;
    }
    try {
        localStorage.setItem(STORAGE_KEY, packageManager);
    } except Exception as error {
        console.warn("Failed to save package manager to localStorage:", error);
    }
}

glob PackageManagerContext = createContext({
    "selectedPackageManager": "pnpm",
    "setPackageManager": _noopPackageManager,
    "isHydrated": False,
});

