    pmState = useState("pnpm");
    selectedPackageManager = pmState[0];
    setSelectedPackageManager = pmState[1];
    hydratedState = useState(False);
    isHydrated = hydratedState[0];
    setIsHydrated = hydratedState[1];

    def setPackageManager(packageManager: PackageManager) {
        setSelectedPackageManager(packageManager);
        setStoredPackageManager(packageManager);
    }

    useEffect(lambda {
        stored = getStoredPackageManager();
        setSelectedPackageManager(stored);
        setIsHydrated(True);
    }, []);

    <PackageManagerContext.Provider
        value={{
            "selectedPackageManager": selectedPackageManager,
            "setPackageManager": setPackageManager,
            "isHydrated": isHydrated,
        }}
    >
        {children}
