def isHttpError(err: object, status: int) -> bool {
    if not isinstance(err, dict) {
        return False;
    }
    if "status" not in err {
        return False;
    }
    errStatus = err["status"];
    if not isinstance(errStatus, int) {
        return False;
    }
    return errStatus == status;
}

def isUnauthorizedLike(err: object) -> bool {
    if isHttpError(err, 401) or isHttpError(err, 403) {
        return True;
    }
    lower = str(err).lower();
    return (
        "unauthorized" in lower
        or "not authenticated" in lower
        or "session expired" in lower
        or "invalid session" in lower
    );
}

def isNetworkLike(err: object) -> bool {
    if not isinstance(err, Exception) {
        return False;
    }
    msg = str(err);
    lower = msg.lower();

    return (
        "fetch" in lower
        or "network" in lower
        or "failed to connect" in lower
        or "net::err" in lower
        or "enotfound" in lower
        or "econnrefused" in lower
        or msg == "Hermes API is unreachable."
    );
}

