"""Kitchen line health inspection: check station temperatures and log every visit."""

node Station {
    has name: str = "";
    has temperature: float = 0.0;

    def is_violation() -> bool {
        return self.temperature > 40.0;
    }
}

walker Inspector {
    has visit_log: list[str] = [];
    has violations: list[str] = [];

    can start with Root entry {
        print("Inspector starting kitchen line sweep");
        visit [-->];
    }

    can inspect with Station entry {
        # Temperature violation check (above 40 C is a flag).
        if here.is_violation() {
            flag = f"VIOLATION at {here.name}: {here.temperature} C";
            print(flag);
            self.violations.append(flag);
        } else {
            print(f"OK at {here.name}: {here.temperature} C");
        }

        # Separate visit log for every station entry.
        entry_note = f"visited {here.name}";
        print(f"LOG: {entry_note}");
        self.visit_log.append(entry_note);

        visit [-->] else { disengage; }
    }
}

with entry {
    grill = Station(name="Grill", temperature=180.0);
    fryer = Station(name="Fryer", temperature=175.0);
    cold_prep = Station(name="ColdPrep", temperature=4.0);

    root ++> grill ++> fryer ++> cold_prep;

    inspector = Inspector();
    root spawn inspector;

    print(f"Total visits logged: {len(inspector.visit_log)}");
    print(f"Total violations flagged: {len(inspector.violations)}");
    for v in inspector.violations {
        print(f"  - {v}");
    }
}
