def rot13_char(char: str) -> str {
    charCode = ord(char);
    baseCode = 97 if charCode >= 97 else 65;
    return chr(((charCode - baseCode + 13) % 26) + baseCode);
}

def:pub rot13(input: str) -> str {

    output: list[str] = [];
    for char in input {
        if ("a" <= char <= "z") or ("A" <= char <= "Z") {
            output.append(rot13_char(char));
        }
        else {
            output.append(char);
        }
    }
    return "".join(output);
}

