    serializePrimitiveParam,
}

obj:pub PathSerializer {
    has path: dict[str, object];
    has url: str;
}

glob:pub PATH_PARAM_RE: str = r"\{[^{}]+\}";

def:pub defaultPathSerializer(pathSerializer: PathSerializer) -> str {
    path = pathSerializer.path;
    url = pathSerializer.url;
    _url = pathSerializer.url;
    matches = re.findall(PATH_PARAM_RE, _url);
    if matches {
        for match in matches {
            explode = False;
            name = match[1:-1];
            style = "simple";
            if name.endswith("*") {
                explode = True;
                name = name[0:-1];
            }
            if name.startswith(".") {
                name = name[1:];
                style = "label";
            } elif name.startswith(";") {
                name = name[1:];
                style = "matrix";
            }
            value = path.get(name);
            if value is None {
                continue;
            }
            if isinstance(value, list) {
                url = url.replace(
                    match,
                    serializeArrayParam({
                        "explode": explode,
                        "name": name,
                        "style": style,
                        "value": value,
                    }),

                    1,
                );
                continue;
            }
            if isinstance(value, dict) {
                url = url.replace(
                    match,
                    serializeObjectParam({
                        "explode": explode,
                        "name": name,
                        "style": style,
                        "value": value,
                        "valueOnly": True,
                    }),
                    1,
                );
                continue;
            }
            if style == "matrix" {
                url = url.replace(
                    match,
                    ";" + serializePrimitiveParam({"name": name, "value": str(value)}),
                    1,
                );
                continue;
            }
            replaceValue = quote(
                ("." + str(value)) if style == "label" else str(value),
                safe="-_.!~*'()",
            );
            url = url.replace(match, replaceValue, 1);
        }
    }
    return url;
}

