def:pub mergeDeep(target: dict[str, object], sources: list[dict[str, object]]) -> dict[str, object] {
    if len(sources) == 0 {
        return target;
    }
    source = sources[0];
    rest = sources[1:];
    if isObject(target) and isObject(source) {
        src = source as dict[str, object];
        for key in src {
            val = src[key];
            if isObject(val) {

                if key not in target or not target[key] {
                    target[key] = {};
                }
                nested = target[key] as dict[str, object];
                mergeDeep(nested, [val as dict[str, object]]);
            } else {
                target[key] = val;
            }
        }
    }
    return mergeDeep(target, rest);
}

