def:pub Modal(
    open: bool,
    onClose: Callable[[], None],
    title: str | None = None,
    description: str | None = None,
    children: object | None = None,
    footer: object | None = None,
    className: str | None = None,
) -> JsxElement | None {
    has mounted: bool = False;

    can with entry {
        mounted = True;
    }

    useEffect(lambda () -> object {
        if not open {
            return lambda () -> object { return None; };
        }
        def handle_key_down(event: KeyboardEvent) -> None {
            if event.key == "Escape" {
                onClose();
            }
        }
