def leftUnwrap(row: str, left: str = "", multiLevel: bool) -> str {
    if (left == "") {
        return row;
    }
    while row.startswith(left) {
        row = row[len(left):];
        if not multiLevel {
            break;
        }
    }
    return row;
}

def rightUnwrap(row: str, right: str = "", multiLevel: bool) -> str {
    if (right == "") {
        return row;

    }
    while row.endswith(right) {
        row = row[0:(len(row) - len(right))];
        if not multiLevel {
            break;
        }
    }
    return row;
}

