glob:pub tzMap: dict[str, str] = {"EST": "America/New_York", "EDT": "America/New_York", "CST": "America/Chicago", "CDT": "America/Chicago", "MST": "America/Denver", "MDT": "America/Denver", "PST": "America/Los_Angeles", "PDT": "America/Los_Angeles", "GMT": "Etc/GMT", "UTC": "Etc/UTC"};

def:pub parseWithTZ(dateTimeStr: str) -> object {
    parts = dateTimeStr.strip().split(" ");
