def:pub calculateTimeBetweenDates(startDate: object, endDate: object) -> dict[str, int] {
    start = dayjs(startDate);
    end = dayjs(endDate);
    years = end.diff(start, "year");
    startPlusYears = start.add(years, "year");
    months = end.diff(startPlusYears, "month");
    startPlusMonths = startPlusYears.add(months, "month");

    days = end.diff(startPlusMonths, "day");
    startPlusDays = startPlusMonths.add(days, "day");
    hours = end.diff(startPlusDays, "hour");
    startPlusHours = startPlusDays.add(hours, "hour");
    minutes = end.diff(startPlusHours, "minute");
    startPlusMinutes = startPlusHours.add(minutes, "minute");
    seconds = end.diff(startPlusMinutes, "second");
    startPlusSeconds = startPlusMinutes.add(seconds, "second");
    milliseconds = end.diff(startPlusSeconds, "millisecond");
    return {"years": years, "months": months, "days": days, "hours": hours, "minutes": minutes, "seconds": seconds, "milliseconds": milliseconds};
