import from "rebound" { Spring, SpringSystem }
import from "react" { useEffect, useState }

def:pub useSpring(targetValue: float = 0, tension: float = 50, friction: float = 3) -> float {
    springPair = useState(None);
    spring = springPair[0];
    setSpring = springPair[1];
    valuePair = useState(targetValue);
    value: float = valuePair[0] as float;
    setValue = valuePair[1];

    useEffect(lambda {
        listener = {
            "onSpringUpdate": lambda (currentSpring: object) -> None {
                getter = getattr(currentSpring, "getCurrentValue");
                setValue(getter.call(None) as float);
            },
        };

        if not spring {
            system = new(SpringSystem);
            creator = getattr(system, "createSpring");
            newSpring = creator.call(None, tension, friction);
            getattr(newSpring, "setCurrentValue").call(None, targetValue);
            setSpring(newSpring);
            getattr(newSpring, "addListener").call(None, listener);
            return;
        }
        return lambda {
            getattr(spring, "removeListener").call(None, listener);
            setSpring(None);
        };
    }, [tension, friction]);

    useEffect(lambda {
        if spring {
            getattr(spring, "setEndValue").call(None, targetValue);
        }
    }, [targetValue]);

    return value;
}

