            onClick={(e) => e.stopPropagation()}
          />
          <div
            className="fixed z-[9997]"
            style={{
              top: spotlight.top,
              left: 0,
              width: spotlight.left,
              height: spotlight.height,
            }}
            onClick={(e) => e.stopPropagation()}
