import re;

glob MATCH_THEME = re.compile(r"theme\((.+?)\)");
glob MATCH_QUOTES = re.compile(r"['\"`]");

obj AssertContext {
    has color: Callable[[str, str | None], str];
}

obj CoreContext {
    has assert_fn: Callable[[bool, Callable[[AssertContext], str]], None];
    has theme: Callable[[str, str], str | dict[str, str]];
}

def:pub replaceThemeValue(value: str, ctx: CoreContext) -> str {

    assert_fn = ctx.assert_fn;
    theme_fn = ctx.theme;
    theme_match = MATCH_THEME.search(value);
    if theme_match is None {
        return value;
    }
    theme_function = theme_match.group(0);
    theme_parameters = re.sub(MATCH_QUOTES, "", theme_match.group(1)).strip();
    parts = theme_parameters.split(",");
    main = parts[0];
    second = parts[1] if len(parts) > 1 else "";
    theme_value: str | dict[str, str] = theme_fn(main, second);
    assert_fn(
        bool(theme_value),
        lambda (ac: AssertContext) {
            return ac.color(
                f"✕ {ac.color(theme_parameters, 'errorLight')} doesn't match a theme value from the config",
                None
            );
        }
    );
    if isinstance(theme_value, dict) and "DEFAULT" in theme_value {
        theme_value = theme_value["DEFAULT"];
    }
    string_value: str = str(theme_value).replace(".", r"\.");
    return value.replace(theme_function, string_value);
}

