node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud: bool = False;
}

walker OrderAuditor {
    has audited: int = 0;
    has skipped: int = 0;
    has halted: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Order entry {
        action = "";
        if here.fraud {
            action = "HALT";
            print(f"[HALT] {here.order_id} flagged fraud (${here.amount}) — walk aborted");
            self.halted = True;
        } elif not here.valid {
            action = "SKIP";
            print(f"[SKIP] {here.order_id} invalid (${here.amount}) — continuing");
            self.skipped += 1;
            visit [-->];
        } else {
            action = "AUDIT";
            print(f"[AUDIT] {here.order_id} OK (${here.amount})");
            self.audited += 1;
            visit [-->];
        }
        if action == "HALT" {
            disengage;
        }
    }
}

