  create(
    { id = "", regExp = "", history = [] },
    done: (
      error: string | null,
      createdItem?: DynamicBookmarkStorageItem,
    ) => void,
  ) {
    const key = _convertToDbmId(id);
    this._setItem(key, { regExp, history }, (errMsg, createdItem) => {
      if (errMsg) return done(errMsg);
      this._addKeyToDbmIds(key, (errMsg) => {
