def rewrite_doc_links(text: str, base: str) -> str {
    pattern = re.compile(r"\]\((\/docs(?:\/[^)#\s]+)?)(#[^)]+)?\)");
    def repl(m: object) -> str {
        rm = m as re.Match;
        pathname = rm.group(1);
        hash_part = rm.group(2) if rm.group(2) is not None else "";
        return f"]({base}{pathname}.md{hash_part})";
    }
    return pattern.sub(repl, text);
}

def documentationIndex(base: str) -> str {
    index = llms(source).index();
    index = re.sub(r"(?m)^#\s+(.+)$", r"## \1", index);
    index = rewrite_doc_links(index, base);
    return index.strip();
}

def docsIndex(origin: str) -> str {
