  return (
    <Tippy
      zIndex={Z_INDICES[KleeZIndex.Tooltip]}
      disabled={isDisabled}
      placement={placement}
      interactive={keepOnHover}
      delay={trigger.includes('click') ? 0 : delay}
      onMount={onMount}
      showOnCreate={showOnCreate}
      trigger={trigger.join(' ')}
      onHide={onHideHandler}
