          })}
          color="white"
          borderRadius={KleeRadius.Md}
          boxShadow={KleeShadow.Md}
          fontSize={KleeFontSize.Sm}
          maxWidth="270px"
          {...attrs}
          {...props}
          style={{ scale, opacity }}
        >
          {typeof label === 'string' && <Text truncate={truncate}>{label}</Text>}
          {typeof label !== 'string' && <Fragment>{label}</Fragment>}
          {useArrow && (
            <Arrow
              css={css({
