                        backdropFilter: `blur(${BLUR_AMOUNT}px)`,
                        clipPath: 'polygon(0 0, 100% 0%, 100% 22%, 0% 100%)',
                        bg: transparentize(0.5, themeGet(`colors.${computedBg}`, '#000')({ theme })),
                      }
                    : {
                        bg: computedBg,
                      }),
                },
              })}
              id="arrow"
              data-popper-arrow
            />
          )}
        </TooltipInner>
      )}
    >
      {children}
    </Tippy>
  )
}

