"""DeepCopy cycle-safety demo: copy a self-referential document graph.

Models the oastools parser bug where generated DeepCopy recurses without
tracking already-copied nodes, overflowing the stack on cyclic documents.
A `CopyWalker` threads a visited map (source-pointer -> already-made copy)
through the traversal so a node reached twice returns its existing copy,
preserving cycle structure rather than just avoiding the crash.
"""

node Schema {
    has name: str = "";
    has children: list = [];
}

node Encoding {
    has name: str = "";
    has children: list = [];
}

node MediaType {
    has name: str = "";
    has children: list = [];
}

edge SchemaChild {}
edge EncodingChild {}
edge MediaEncoding {}

walker CopyWalker {
    has visited: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can copy_schema with Schema entry {
        key = id(here);
        if key in self.visited {
            print(f"cycle hit on schema {here.name} -> reusing copy");
            return;
        }
        new_schema = Schema(name=here.name);
        self.visited[key] = new_schema;
        print(f"copying schema {here.name}");
        visit [->:SchemaChild:->];
    }

    can copy_encoding with Encoding entry {
        key = id(here);
        if key in self.visited {
            print(f"cycle hit on encoding {here.name} -> reusing copy");
            return;
        }
        new_enc = Encoding(name=here.name);
        self.visited[key] = new_enc;
