"""Family Genealogy Graph: evidence-backed ancestry and kinship research.

Models PERSON, NAME_VARIANT, EVIDENCE, RESEARCH_TASK as node archetypes.
Relationships are typed edges carrying confidence and source backing.
A PedigreeWalker traverses ancestry chains, a ResearchPlanner walks the
graph collecting unresolved candidates and proposes follow-up tasks, and
an InvalidationWalker cascades a disputed flag through evidence chains so
downstream nodes can react. Cycle policy is explicit because Jac 0.36.1
walkers have no built-in once-per-node visit set.
"""

node Person {
    has name: str = "";
    has birth_year: int = 0;
    has death_year: int = 0;
    has is_hypothesis: bool = False;
}

node NameVariant {
    has spelling: str = "";
    has script: str = "latin";
    has language: str = "und";
}

node Evidence {
    has source_kind: str = "manual";
    has confidence: float = 0.5;
    has verified: bool = False;
}

node ResearchTask {
    has title: str = "";
    has priority: int = 1;
    has resolved: bool = False;
}

edge Kinship {
    has kind: str = "unknown";
    has confidence: float = 0.0;
}

edge NamedAs {
}

edge SupportedBy {
}

edge SuggestedBy {
}

walker PedigreeWalker {
    has seen: list[str] = [];
    has max_depth: int = 4;
    has depth: int = 0;
    has chain: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can step with Person entry {
        pid = here.name;
        already = False;
        for s in self.seen {
            if s == pid {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(pid);
        self.chain.append(pid);
        print(f"{'  ' * self.depth}[depth {self.depth}] {pid} "
              f"(hyp={here.is_hypothesis})");
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth = self.depth + 1;
        visit [->:Kinship:->];
    }

    can pass_through with NameVariant | Evidence | ResearchTask entry {
        visit [-->];
    }
}

walker ResearchPlanner {
    has tasks: list = [];
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can inspect with Person entry {
        pid = here.name;
        already = False;
        for s in self.seen {
            if s == pid {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(pid);

        if here.is_hypothesis {
            self.tasks.append({
                "title": f"Confirm identity of hypothetical person {pid}",
                "priority": 2
            });
        }

        visit [here->:SupportedBy:->];
    }

    can scan_evidence with Evidence entry {
        if not here.verified and here.confidence < 0.7 {
            self.tasks.append({
                "title": f"Re-verify {here.source_kind} evidence (conf={here.confidence})",
                "priority": 1
            });
        }
        visit [-->];
    }

    can skip_node with NameVariant | ResearchTask entry {
        visit [-->];
    }
}

walker InvalidationWalker {
    has seen: list[str] = [];
    has reason: str = "disputed";

    can start with Root entry {
        visit [-->];
    }

    can invalidate with Person entry {
        pid = here.name;
        already = False;
        for s in self.seen {
            if s == pid {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen.append(pid);
        print(f"invalidating person {pid} due to: {self.reason}");
        visit [-->];
    }

    can flag_evidence with Evidence entry {
        if not here.verified {
            here.confidence = 0.0;
            print(f"  evidence ({here.source_kind}) confidence -> 0.0");
        }
        visit [-->];
    }

    can pass_through with NameVariant | ResearchTask entry {
        visit [-->];
    }
}

