def swapCharacters(passphrase: str) -> str {
    sequence: list[bool] = getBooleanSequence(len(passphrase)) as list[bool];
    result: str = "";
    for idx = 0 while idx < len(passphrase) with idx += 1 {
        if sequence[idx] {
            ch: str = passphrase[idx].lower();
