def:pub checkLeapYear(input: str) -> str {
    if not input {
        return "";
    }
    years = [y.strip() for y in input.split("\n") if y.strip() != ""];
    results = [];

    for yearStr in years {
        if not yearStr.isdigit() or len(yearStr) > 4 {
            results.append(f"{yearStr}: Invalid year");
        } else {
            year = int(yearStr);
            msg = "is a leap year." if isLeapYear(year) else "is not a leap year.";
            results.append(f"{year} {msg}");
        }
    }
    return "\n".join(results);
}

