def:pub fuzzyMatch(query: str, target: str) -> FuzzyMatch | None {

    if not query or not target {
        return None;
    }
    queryLower = query.lower();
    targetLower = target.lower();
    exactIndex = targetLower.find(queryLower);
    if exactIndex != -1 {
        indices: list[int] = [];
        endIndex = exactIndex + len(queryLower);
        for i = exactIndex while i < endIndex with i += 1 {
            indices.append(i);
        }
        positionBonus = 1.0 - ((float(exactIndex) / float(len(target))) * 0.1);
        ratioBonus = float(len(queryLower)) / float(len(target));
        score = min((0.9 + (ratioBonus * 0.1)), 1.0) * positionBonus;
        return FuzzyMatch(score=score, matchedIndices=indices);
    }
    queryIdx = 0;
    matchedIndices: list[int] = [];
    consecutiveMatches = 0;
    maxConsecutive = 0;
    lastMatchIdx = -1;
    for targetIdx = 0 while targetIdx < len(targetLower) and queryIdx < len(queryLower) with targetIdx += 1 {
        if targetLower[targetIdx] == queryLower[queryIdx] {
            matchedIndices.append(targetIdx);
            if lastMatchIdx == (targetIdx - 1) {
                consecutiveMatches += 1;
                maxConsecutive = max(maxConsecutive, consecutiveMatches);
            } else {
                consecutiveMatches = 1;
            }
            lastMatchIdx = targetIdx;
            queryIdx += 1;
        }
    }
    if queryIdx != len(queryLower) {
        return None;
    }
    matchRatio = float(len(queryLower)) / float(len(target));
    consecutiveBonus = float(maxConsecutive) / float(len(queryLower));
    spread = (matchedIndices[len(matchedIndices) - 1] - matchedIndices[0]) + 1;
    compactness = float(len(queryLower)) / float(spread);
    wordStartBonus = 0.0;
    for idx in matchedIndices {
        if idx == 0 or targetLower[idx - 1] == " " or targetLower[idx - 1] == "-" or targetLower[idx - 1] == "_" {
            wordStartBonus += 0.1;
        }
    }
    wordStartBonus = min(wordStartBonus, 0.3);
    score = min(
        (((((matchRatio * 0.3) + (consecutiveBonus * 0.3)) + (compactness * 0.2)) + wordStartBonus) + 0.1) * 0.85,
        0.85
    );
    return FuzzyMatch(score=score, matchedIndices=matchedIndices);
}

