import from fast_xml_parser { XMLParser, XMLBuilder, XMLValidator }

def beautifyXml(input: str, _options: InitialValuesType) -> str {

    valid = XMLValidator.validate(input);
    if valid is not True {
        if isinstance(valid, dict) and valid.get("err") {
            err = valid["err"];
            return f"Invalid XML: {err['msg']} (line {err['line']}, col {err['col']})";
        }
        return "Invalid XML";
    }
    try {
        xmlParser = XMLParser();
        parsed = xmlParser.parse(input);
        builder = XMLBuilder({"format": True, "indentBy": "  "});
        return builder.build(parsed);
    } except Exception as e {
        return f"Invalid XML: {str(e)}";
    }
}

