type KubeconfigStatus = dict[str, bool | str | None];

def:pub parseKubeconfigStatus(value: object) -> KubeconfigStatus {
    if not value or not isinstance(value, dict) {
        raise ValueError("Invalid kubeconfig status response.");
    }
    configured = value["configured"];
    updatedAt = value["updatedAt"];
    if not isinstance(configured, bool) or (updatedAt is not None and not isinstance(updatedAt, str)) {
        raise ValueError("Invalid kubeconfig status response.");
    }
    return {"configured": configured, "updatedAt": updatedAt};
}

def:pub formatUpdatedAt(updatedAt: str | None) -> str {

    if not updatedAt {
        return "Not available";
    }
    try {
        normalized = updatedAt.replace("Z", "+00:00");
        date = datetime.fromisoformat(normalized);
    } except Exception {
        return "Not available";
    }
    return date.strftime("%b %d, %Y, %I:%M %p");
}

