def:pub applyAIFieldResult(config: dict[str, object], target: dict[str, object]) -> dict[str, object] {
    moduleKey = target["moduleKey"] as str;
    fieldKey = target["fieldKey"] as str;
    itemIndex = target.get("itemIndex");
    value = target.get("value", "");
    if not isAIImprovementSupported(moduleKey, fieldKey) {
        return config;
    }
    if moduleKey == "aboutme" {
        aboutme = config.get("aboutme") as dict[str, object] | None;
        base = aboutme if aboutme else {"aboutme_desc": ""};
        return {**config, "aboutme": {**base, fieldKey: value}};
    }
    if moduleKey == "workExpList" or moduleKey == "projectList" {

        if not isinstance(itemIndex, int) {
            return config;
        }
        entries = (config.get(moduleKey) as list[dict[str, object]] | None) or [];
        if itemIndex < 0 or itemIndex >= len(entries) {
            return config;
        }
        currentItem = entries[itemIndex];
        entries = entries[:itemIndex] + [{**currentItem, fieldKey: value}] + entries[itemIndex + 1:];
        return {**config, moduleKey: entries};
    }
    return config;
}

