def _appendSearchParams(urlStr: str, params: dict[str, object]) -> str {
    result = urlStr;
    for (key, value) in params.items() {
        joiner = "&" if "?" in result else "?";
        result = f"{result}{joiner}{key}={value}";
    }
    return result;
}

def _linkVisitor(linkNode: dict[str, object], params: dict[str, object]) {
    children = linkNode["children"] as list[dict[str, str]];
    urlStr = linkNode["url"] as str;
    if urlStr.startswith(codesandboxBaseUrl) and children[0]["value"] {
        updated = _appendSearchParams(urlStr, params);
        linkNode["url"] = updated;
        children[0]["value"] = updated;
    }
}

def:pub remarkCodeSandboxURLUpdater(options: dict[str, object] | None = None) -> Callable[[dict[str, object]], None] {

    params: dict[str, object] = defaultParams;
    if options is not None and "params" in options {
        params = options["params"] as dict[str, object];
    }
    def transform(tree: dict[str, object]) {
        visitTree(tree, "link", lambda (linkNode: dict[str, object]) { _linkVisitor(linkNode, params); });
    }
    return transform;
}

