import from pdfx.redact.lookup { resolve }

def:pub readContent(context: PDFContext, page: PDFPage) -> bytes | None {
    contents = page.node.Contents();
    if contents is None {
        return None;
    }
    streams: list[PDFObject] = [];
    if isinstance(contents, PDFArray) {
        for i in range(contents.size()) {
            streams.append(contents.get(i));
        }
    } else {
        streams.append(contents);
    }

    parts: list[bytes] = [];
    for ref in streams {
        stream = resolve(context, ref);
        if not isinstance(stream, PDFRawStream) {
            return None;
        }
        parts.append(decodePDFRawStream(stream).decode());
    }
    total = sum(len(part) + 1 for part in parts);
    joined = bytearray(total);
    offset = 0;
    for part in parts {
        joined[offset : offset + len(part)] = part;
        offset += len(part);
        joined[offset] = 10;
        offset += 1;
    }
    return bytes(joined);
}

