def:pub secondsToMinutesAndSeconds(seconds: float) -> str {
    if seconds < 0 {
        return "--:--";
    }

    minutes = int(seconds // 60);
    remainingSeconds = int(seconds % 60);
    minutesStr = str(minutes).rjust(2, "0");
    secondsStr = str(remainingSeconds).rjust(2, "0");
    return f"{minutesStr}:{secondsStr}";
}
